import { FileText, Search } from "lucide-react";
import { Link } from "react-router-dom";
import { useState, useEffect } from "react";

export default function Consult() {
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedPriority, setSelectedPriority] = useState("all");
  const [consults, setConsults] = useState([]);
  const [loading, setLoading] = useState(true);

  // Dummy data simulating backend consults
  useEffect(() => {
    const dummyConsults = [
      {
        id: 1,
        patient_name: "John Doe",
        patient_identifier: "JD12345",
        age: 34,
        gender: "Male",
        scan_type: "Chest X-ray",
        ai_findings: [
          { name: "Pneumonia", recommendations: ["Antibiotics", "Rest"], color: "#F59E0B", probability: 85 },
          { name: "Atelectasis", recommendations: ["Follow-up X-ray"], color: "#F59E0B", probability: 40 }
        ],
        priority: "high"
      },
      {
        id: 2,
        patient_name: "Jane Smith",
        patient_identifier: "JS67890",
        age: 29,
        gender: "Female",
        scan_type: "CT Scan",
        ai_findings: [
          { name: "Normal", recommendations: ["Routine check-up"], color: "#10B981", probability: 100 }
        ],
        priority: "low"
      },
      {
        id: 3,
        patient_name: "Alice Johnson",
        patient_identifier: "AJ24680",
        age: 45,
        gender: "Female",
        scan_type: "MRI",
        ai_findings: [
          { name: "Tumor", recommendations: ["Refer to oncologist"], color: "#EF4444", probability: 95 }
        ],
        priority: "critical"
      }
    ];

    setConsults(dummyConsults);
    setLoading(false);
  }, []);

  const handleSendToRadiologist = (id) => {
    alert(`Simulated: Send consult ID ${id} to radiologist`);
  };

  const getPriorityColor = (priority) => {
    switch (priority) {
      case 'critical': return 'text-red-400 bg-red-400/10 border-red-400';
      case 'high': return 'text-orange-400 bg-orange-400/10 border-orange-400';
      case 'medium': return 'text-yellow-400 bg-yellow-400/10 border-yellow-400';
      case 'low': return 'text-green-400 bg-green-400/10 border-green-400';
      default: return 'text-gray-400 bg-gray-400/10 border-gray-400';
    }
  };

  const filteredConsults = consults.filter(c => {
    const matchesSearch =
      c.patient_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      c.patient_identifier.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesPriority = selectedPriority === 'all' || c.priority === selectedPriority;
    return matchesSearch && matchesPriority;
  });

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-cyan-900 text-white text-lg">
        Loading consultations...
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-cyan-900">
      {/* Header */}
      <header className="bg-gray-800 border-b border-gray-700">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center">
              <div className="bg-green-500 p-2 rounded-lg mr-3">
                <FileText className="h-6 w-6 text-white" />
              </div>
              <h1 className="text-xl font-bold text-white">MedVision AI Lab</h1>
            </div>
            <nav className="flex space-x-8">
              <Link to="/" className="text-gray-300 hover:text-white font-medium px-3 py-2">
                Uploads
              </Link>
              <Link to="/results" className="text-gray-300 hover:text-white font-medium px-3 py-2">
                Diagnostic Analysis
              </Link>
              <button className="text-green-400 font-semibold border-b-2 px-3 py-2">
                Consult
              </button>
            </nav>
          </div>
        </div>
      </header>

      {/* Search & Filter */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="mb-6 flex flex-col sm:flex-row gap-4">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-5 w-5" />
            <input
              type="text"
              placeholder="Search patients..."
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
              className="w-full bg-gray-800 text-white pl-10 pr-4 py-3 rounded-xl border border-gray-600 focus:border-green-400 focus:outline-none"
            />
          </div>
          <div className="flex gap-3">
            <select
              value={selectedPriority}
              onChange={e => setSelectedPriority(e.target.value)}
              className="bg-gray-800 text-white px-4 py-3 rounded-xl border border-gray-600 focus:border-green-400 focus:outline-none"
            >
              <option value="all">All Priorities</option>
              <option value="critical">Critical</option>
              <option value="high">High</option>
              <option value="medium">Medium</option>
              <option value="low">Low</option>
            </select>
          </div>
        </div>

        {/* Consults Table */}
        <div className="bg-gray-800 rounded-2xl shadow-xl overflow-hidden">
          <div className="grid grid-cols-12 gap-4 px-6 py-4 bg-gray-750 border-b border-gray-700 text-gray-400 font-semibold text-sm">
            <div className="col-span-4">Patient Info</div>
            <div className="col-span-2">Scan Type</div>
            <div className="col-span-2">AI Findings</div>
            <div className="col-span-1">Priority</div>
            <div className="col-span-3">Actions</div>
          </div>

          <div className="divide-y divide-gray-700">
            {filteredConsults.map(c => (
              <div key={c.id} className="grid grid-cols-12 gap-4 px-6 py-4 hover:bg-gray-750 transition-colors">
                <div className="col-span-4">
                  <div className="text-white font-semibold">{c.patient_name}</div>
                  <div className="text-gray-400 text-sm">{c.patient_identifier}</div>
                  <div className="text-gray-400 text-sm">{c.age} yrs, {c.gender}</div>
                </div>
                <div className="col-span-2 text-gray-400">{c.scan_type}</div>
                <div className="col-span-2 text-gray-400">
                  {c.ai_findings.map(f => f.name).join(', ')}
                </div>
                <div className={`col-span-1 text-center border px-2 py-1 rounded-xl text-sm font-semibold ${getPriorityColor(c.priority)}`}>
                  {c.priority}
                </div>
                <div className="col-span-3 flex gap-2">
                  <button
                    onClick={() => handleSendToRadiologist(c.id)}
                    className="bg-green-500 text-white px-3 py-1 rounded hover:bg-green-600"
                  >
                    Send
                  </button>
                </div>
              </div>
            ))}
          </div>

          {filteredConsults.length === 0 && (
            <div className="text-center py-12 text-gray-400">
              No consults found
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
